/* Site-owned, local translations. English is the primary and no-JavaScript language. */
(() => {
  'use strict';
  const dictionaries = window.FLUIDTECH_TRANSLATIONS || {};
  const supported = ['en', 'de', 'es', 'fr'];
  const storageKey = 'fluidtech-language';
  let language = 'en';
  let stored;
  try { stored = localStorage.getItem(storageKey); } catch (_) { /* Storage is optional. */ }
  const requested = new URLSearchParams(location.search).get('lang');
  if (supported.includes(requested)) language = requested;
  else if (supported.includes(stored)) language = stored;
  const originals = new WeakMap();
  const attributes = new WeakMap();
  const skip = 'script, style, noscript, [translate="no"], [data-no-translate]';
  const normalize = value => value.replace(/\s+/g, ' ').trim();
  function t(source) {
    const text = normalize(source);
    if (language === 'en') return text;
    const dict = dictionaries[language];
    if (dict[text]) return dict[text];
    // Runtime counts and actions are generated by the equipment, gallery and form scripts.
    const arrow = text.match(/^(.*?)( [↗↓])$/);
    if (arrow && dict[arrow[1]]) return dict[arrow[1]] + arrow[2];
    const count = text.match(/^(\d+) machines?( matching your selection)?$/);
    if (count) {
      const noun = { de: ['Anlage', 'Anlagen'], es: ['equipo', 'equipos'], fr: ['équipement', 'équipements'] }[language][count[1] === '1' ? 0 : 1];
      const suffix = count[2] ? { de: ' passend zu Ihrer Auswahl', es: ' que coinciden con su selección', fr: ' correspondant à votre sélection' }[language] : '';
      return count[1] + ' ' + noun + suffix;
    }
    return text;
  }
  function render(source) {
    const leading = source.match(/^\s*/)[0], trailing = source.match(/\s*$/)[0];
    return leading + t(source) + trailing;
  }
  function translateText(node) {
    if (!node.parentElement || node.parentElement.closest(skip + ', textarea') || !node.textContent.trim()) return;
    let record = originals.get(node);
    // A component replacing a text value starts a new English source, rather than reusing stale text.
    if (!record || node.textContent !== record.rendered) record = { source: node.textContent };
    record.rendered = language === 'en' ? record.source : render(record.source);
    if (node.textContent !== record.rendered) node.textContent = record.rendered;
    originals.set(node, record);
  }
  function translateAttributes(element) {
    if (element.closest(skip)) return;
    const names = ['aria-label', 'placeholder', 'alt', 'title'];
    if (element.matches('meta[name="description"], meta[property="og:description"], meta[property="og:title"]')) names.push('content');
    let records = attributes.get(element) || {};
    for (const name of names) {
      if (!element.hasAttribute(name)) continue;
      const value = element.getAttribute(name);
      let record = records[name];
      if (!record || value !== record.rendered) record = { source: value };
      record.rendered = language === 'en' ? record.source : render(record.source);
      if (value !== record.rendered) element.setAttribute(name, record.rendered);
      records[name] = record;
    }
    attributes.set(element, records);
  }
  let observer;
  const observerOptions = { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['aria-label', 'placeholder', 'alt', 'title', 'content'] };
  function translateTree(root = document.documentElement) {
    if (root.nodeType === Node.TEXT_NODE) return translateText(root);
    if (root.nodeType !== Node.ELEMENT_NODE || root.closest(skip)) return;
    translateAttributes(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (node.nodeType === Node.ELEMENT_NODE && node.matches(skip)) return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    while (walker.nextNode()) {
      if (walker.currentNode.nodeType === Node.TEXT_NODE) translateText(walker.currentNode);
      else translateAttributes(walker.currentNode);
    }
  }
  const notify = document.createElement('span');
  notify.className = 'sr-only'; notify.setAttribute('role', 'status'); notify.setAttribute('data-no-translate', '');
  document.body.append(notify);
  function apply(next, announce = false) {
    if (!supported.includes(next)) return;
    observer?.disconnect();
    language = next;
    document.documentElement.lang = language;
    try { localStorage.setItem(storageKey, language); } catch (_) { /* Keep this page functional without storage. */ }
    document.querySelectorAll('[data-language-select]').forEach(select => { select.value = language; });
    translateTree();
    // A selected language is shareable, and survives reload even when storage is blocked.
    if (announce || requested) {
      const url = new URL(location.href);
      if (language === 'en') url.searchParams.delete('lang'); else url.searchParams.set('lang', language);
      history.replaceState(null, '', url);
    }
    observer?.observe(document.documentElement, observerOptions);
    document.dispatchEvent(new CustomEvent('fluidtech:languagechange', { detail: { language } }));
    if (announce) notify.textContent = t('Page language updated') + ': ' + { en: 'English', de: 'Deutsch', es: 'Español', fr: 'Français' }[language];
  }
  window.FluidtechI18n = { t, get language() { return language; } };
  document.querySelectorAll('[data-language-select]').forEach(select => { select.disabled = false; select.addEventListener('change', () => apply(select.value, true)); });
  observer = new MutationObserver(records => {
    observer.disconnect();
    const roots = new Set();
    for (const mutation of records) {
      if (mutation.type === 'childList') mutation.addedNodes.forEach(node => roots.add(node));
      else roots.add(mutation.target);
    }
    roots.forEach(node => { if (node.isConnected) translateTree(node); });
    observer.observe(document.documentElement, observerOptions);
  });
  // Carry the visitor's choice through internal links, including enquiry context.
  document.addEventListener('click', event => {
    const link = event.target.closest('a[href]');
    if (!link || link.hasAttribute('download')) return;
    const url = new URL(link.href, location.href);
    if (url.origin !== location.origin || !['http:', 'https:'].includes(url.protocol)) return;
    if (language === 'en') url.searchParams.delete('lang'); else url.searchParams.set('lang', language);
    link.href = url.href;
  }, true);
  apply(language);
})();
